#!/usr/bin/env python3
"""Check every relative markdown link and image in the agency repo.

Rules:
  * only local relative targets are checked (http(s), mailto, #anchor skipped)
  * `<path>#<anchor>` resolves if the path exists; the anchor is validated
    against headings/slugs in the target when that target is markdown
  * files generated by the upstream vendored tree are checked too, so a broken
    link we add anywhere is caught
  * targets are resolved from the file's own directory (standard markdown)

Usage:
    python3 scripts/check-links.py [--verbose]

Exit code 1 when at least one link is broken.
"""

from __future__ import annotations

import argparse
import re
import sys
import unicodedata
from pathlib import Path
from urllib.parse import unquote

ROOT = Path(__file__).resolve().parent.parent

SKIP_DIRS = {".git", "node_modules", "__pycache__", ".arena"}

# [text](target "title") | ![alt](target) | [ref]: target
INLINE = re.compile(r"!?\[[^\]]*\]\(\s*(<[^>]+>|[^)\s]+)(?:\s+[\"'(][^)]*)?\s*\)")
REFERENCE = re.compile(r"^\s{0,3}\[[^\]]+\]:\s*(\S+)", re.MULTILINE)
EXTERNAL = re.compile(r"^(?:[a-zA-Z][a-zA-Z0-9+.-]*:|//)")


def markdown_files() -> list[Path]:
    out = []
    for path in ROOT.rglob("*.md"):
        if any(part in SKIP_DIRS for part in path.relative_to(ROOT).parts):
            continue
        out.append(path)
    return sorted(out)


def slugify(text: str) -> str:
    """Approximate GitHub's heading slug: lowercase, drop punctuation, dash spaces."""
    text = text.strip().lower()
    text = re.sub(r"<[^>]+>", "", text)
    text = re.sub(r"[^\w\s\u0080-\uffff-]", "", text)
    text = text.replace(" ", "-")
    return unicodedata.normalize("NFC", text)


def anchors_of(path: Path) -> set[str]:
    anchors: set[str] = set()
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return anchors
    in_fence = False
    for line in text.splitlines():
        stripped = line.strip()
        if stripped.startswith("```") or stripped.startswith("~~~"):
            in_fence = not in_fence
            continue
        if in_fence:
            continue
        m = re.match(r"^\s{0,3}#{1,6}\s+(.*)$", line)
        if m:
            anchors.add(slugify(m.group(1)))
        # explicit HTML anchors, e.g. <a id="engineering"></a>
        for anchor in re.findall(r"""<a\s+[^>]*?(?:id|name)=["']([^"']+)["']""", line):
            anchors.add(anchor)
    return anchors


def targets_of(path: Path) -> list[tuple[int, str]]:
    found: list[tuple[int, str]] = []
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return found
    in_fence = False
    for lineno, line in enumerate(text.splitlines(), 1):
        stripped = line.strip()
        if stripped.startswith("```") or stripped.startswith("~~~"):
            in_fence = not in_fence
            continue
        if in_fence:
            continue
        for match in INLINE.finditer(line):
            target = match.group(1)
            if target.startswith("<") and target.endswith(">"):
                target = target[1:-1]
            found.append((lineno, target))
        ref = REFERENCE.match(line)
        if ref:
            found.append((lineno, ref.group(1)))
    return found


def resolve(source: Path, target: str) -> tuple[Path | None, str | None]:
    """Return (path, anchor) or (None, reason).

    A target of the form '#anchor' resolves to the source file itself.
    """
    target = unquote(target.split("?")[0])
    anchor = None
    if "#" in target:
        target, anchor = target.split("#", 1)
        anchor = anchor or None
    if not target:
        # pure in-page anchor: the link target is this file
        return source, anchor
    base = source.parent
    candidate = (base / target).resolve()
    if candidate.is_dir():
        for index in ("README.md", "index.md"):
            if (candidate / index).is_file():
                return candidate / index, anchor
        return None, "directory without README/index"
    if candidate.is_file():
        return candidate, anchor
    # tolerate targets that were written relative to the repo root
    alt = (ROOT / target.lstrip("/")).resolve()
    if alt.is_file():
        return alt, anchor
    return None, "file not found"


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--verbose", "-v", action="store_true")
    args = ap.parse_args(argv)

    files = markdown_files()
    broken: list[str] = []
    checked = 0
    cached_anchors: dict[Path, set[str]] = {}

    for source in files:
        for lineno, target in targets_of(source):
            if not target or EXTERNAL.match(target):
                continue
            checked += 1
            resolved, reason = resolve(source, target)
            rel = source.relative_to(ROOT)
            if resolved is None:
                broken.append(f"{rel}:{lineno}: broken link -> {target} ({reason})")
                continue
            anchor = reason  # resolve() returns the anchor in the second slot
            # Anchors are only validated in docs we own; the vendored upstream
            # tree is third-party content whose anchors GitHub renders.
            if anchor and resolved.suffix == ".md" and "upstream" not in rel.parts:
                if resolved not in cached_anchors:
                    cached_anchors[resolved] = anchors_of(resolved)
                anchors = cached_anchors[resolved]
                if anchor not in anchors and not re.fullmatch(r"[0-9a-fA-F-]{20,}", anchor):
                    broken.append(
                        f"{rel}:{lineno}: missing anchor '#{anchor}' in "
                        f"{resolved.relative_to(ROOT)}"
                    )

    if args.verbose:
        print(f"scanned {len(files)} markdown files, {checked} local links")

    for problem in broken:
        print(f"[ERR] {problem}", file=sys.stderr)
    if broken:
        print(f"[ERR] {len(broken)} broken link(s)", file=sys.stderr)
        return 1
    print(f"[OK]  {checked} local links across {len(files)} files resolve")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
